# R/raster-info.R
# Manual file - NOT generated by orchestrate.R
# Provides raster info methods and GDALRasterBand class

# ============================================================================
# GDALRasterBand S7 class
# ============================================================================

#' GDALRasterBand class
#'
#' Represents a raster band within a GDAL dataset.
#'
#' @export
GDALRasterBand <- S7::new_class(
    "GDALRasterBand",
    parent = GDALMajorObject,
    properties = list(
        .ptr = S7::class_any
    )
)

# ============================================================================
# Dataset dimension methods (properties in SWIG, need manual bindings)
# ============================================================================

#' Get raster width
#'
#' @param x A GDALDataset object
#' @return Integer width in pixels
#' @export
get_raster_xsize <- S7::new_generic("get_raster_xsize", "x")

S7::method(get_raster_xsize, GDALDataset) <- function(x) {
    GDAL7_dataset_get_raster_xsize(x@.ptr)
}

#' Get raster height
#'
#' @param x A GDALDataset object
#' @return Integer height in pixels
#' @export
get_raster_ysize <- S7::new_generic("get_raster_ysize", "x")

S7::method(get_raster_ysize, GDALDataset) <- function(x) {
    GDAL7_dataset_get_raster_ysize(x@.ptr)
}

#' Get number of raster bands
#'
#' @param x A GDALDataset object
#' @return Integer number of bands
#' @export
get_raster_count <- S7::new_generic("get_raster_count", "x")

S7::method(get_raster_count, GDALDataset) <- function(x) {
    GDAL7_dataset_get_raster_count(x@.ptr)
}

# ============================================================================
# Override get_raster_band to return our GDALRasterBand class
# ============================================================================

# Note: This overrides the generated method which tries to return a class that
# didn't exist. We define the method here after GDALRasterBand is defined.

S7::method(get_raster_band, GDALDataset) <- function(x, nBand) {
    ptr <- GDAL7_dataset_get_band(x@.ptr, as.integer(nBand))
    GDALRasterBand(.ptr = ptr)
}

