# ============================================================================
# Print method for GDALRasterBand
# ============================================================================

S7::method(print, GDALRasterBand) <- function(x, ...) {
    cat("<GDALRasterBand>\n")
    cat("  Band:       ", get_band_number(x), "\n", sep = "")
    cat("  Size:       ", get_xsize(x), " x ", get_ysize(x), "\n", sep = "")
    cat("  Type:       ", get_data_type_name(x), "\n", sep = "")
    
    block <- get_block_size(x)
    cat("  Block size: ", block["x"], " x ", block["y"], "\n", sep = "")
    
    nodata <- get_nodata_value(x)
    if (!is.null(nodata)) {
        cat("  NoData:     ", nodata, "\n", sep = "")
    }
    
    desc <- get_description(x)
    if (nchar(desc) > 0) {
        cat("  Description:", desc, "\n")
    }
    
    color <- get_color_interpretation_name(x)
    if (nchar(color) > 0 && color != "Undefined") {
        cat("  Color:      ", color, "\n", sep = "")
    }
    
    invisible(x)
}
